const rows = (r: unknown): Array<Record<string, unknown>> => (Array.isArray(r) ? r : (r as { rows?: Array<Record<string, unknown>> }).rows ?? []);
if (!ctx.user || ctx.user.role !== "{{param.payer_role}}") return true;
if (String(row.status ?? "pending") !== "pending" || row.paid_at) return "A payment starts as pending until Stripe confirms it.";
const rec = rows(await ctx.db.query('select "{{param.price_field}}" as price from "{{param.attach_to}}" where id = $1', [row.record_id]))[0];
if (!rec) return "You can't pay for that.";
return Math.abs(Number(rec.price) - Number(row.amount)) < 0.005 || "The amount must match the price.";

if (!ctx.old || !ctx.user || ctx.user.role !== "{{param.payer_role}}") return true;
for (const f of ["record_id", "payer_id", "amount", "currency", "status", "stripe_session_id", "paid_at"]) {
  if (String(ctx.old[f] ?? "") !== String(row[f] ?? "")) return "Only Stripe can change a payment.";
}
return String(row.check ?? "idle") === "requested" || String(row.check ?? "") === String(ctx.old.check ?? "") || "Only Stripe can change a payment.";

