const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Payments aren't set up yet: connect Stripe or add STRIPE_SECRET_KEY in the project settings.");
if (!ctx.app.url.startsWith("http")) throw new Error("This app's address isn't known yet. Open it from the preview or publish it, then try again.");
const done = ctx.app.url + "/my-payments?checkout=done";
const back = ctx.app.url + "/my-payments";
const form = (pairs: Array<[string, string]>) => pairs.map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");
if (!user) throw new Error("Sign in to pay.");
const id = String(input["record_id"] ?? "");
const record = await ctx.db.get("{{param.attach_to}}", id);
if (!record) throw new Error("You can't pay for that.");
const me = (await ctx.db.list("{{param.payer_role}}", { filter: { user_id: user.id }, limit: 1 }))[0];
if (!me) throw new Error("Your account isn't set up yet. Try again in a moment.");
const payerRef = "{{param.payer_ref}}";
if (payerRef && String(record[payerRef] ?? "") !== String(me["id"])) throw new Error("That isn't yours to pay for.");
const cents = Math.round(Number(record["{{param.price_field}}"] ?? 0) * 100);
if (!Number.isFinite(cents) || cents < 50) throw new Error("There's nothing to pay for this one (the minimum is 0.50).");
const prior = await ctx.db.list("payment", { filter: { record_id: id }, limit: 50 });
if (prior.some((p) => String(p["status"]) === "paid")) throw new Error("This is already paid.");
const label = String(record["{{param.attach_to.label_field}}"] ?? "") || "Payment";
const res = await ctx.http.fetch("https://api.stripe.com/v1/checkout/sessions", {
  method: "POST",
  headers: { authorization: `Bearer ${key}`, "content-type": "application/x-www-form-urlencoded" },
  body: form([["mode", "payment"], ["line_items[0][quantity]", "1"], ["line_items[0][price_data][currency]", "{{param.currency}}"], ["line_items[0][price_data][unit_amount]", String(cents)], ["line_items[0][price_data][product_data][name]", label], ["success_url", done], ["cancel_url", back], ["client_reference_id", id], ["customer_email", user.email], ["metadata[record_id]", id]]),
});
const session = res.json<{ id?: string; url?: string; error?: { message?: string } }>();
if (!res.ok || !session?.id || !session.url) throw new Error(`Stripe couldn't start checkout: ${session?.error?.message ?? res.status}`);
const pay = await ctx.db.create("payment", { record_id: id, payer_id: String(me["id"]), amount: cents / 100, currency: "{{param.currency}}", status: "pending", check: "idle", stripe_session_id: session.id });
return { url: session.url, payment_id: String(pay["id"]) };

type Obj = Record<string, unknown>;
const type = String(row["type"] ?? "");
const obj = ((row["data"] as { object?: Obj } | undefined)?.object ?? {}) as Obj;
if (obj["mode"] !== "payment") return;
const sessionId = typeof obj["id"] === "string" ? obj["id"] : "";
const pay = sessionId ? (await ctx.db.list("payment", { filter: { stripe_session_id: sessionId }, limit: 1 }))[0] : undefined;
if (!pay) { ctx.log(`stripe: no payment for checkout ${sessionId}`); return; }
if (String(pay["status"]) === "paid") return;
const id = String(pay["id"]);
if (type === "checkout.session.completed" || type === "checkout.session.async_payment_succeeded") {
  if (obj["payment_status"] !== "paid") { ctx.log(`stripe: checkout ${sessionId} completed, payment still ${String(obj["payment_status"] ?? "pending")}`); return; }
  // The amount Stripe charged must be the amount the server set.
  const expected = Math.round(Number(pay["amount"] ?? 0) * 100);
  if (obj["amount_total"] !== expected) { ctx.log(`stripe: checkout ${sessionId} charged ${String(obj["amount_total"])}, expected ${expected} — not marked paid`); return; }
  await ctx.db.update("payment", id, { status: "paid", paid_at: ctx.now().toISOString() });
  ctx.log(`stripe: payment ${id} paid`);
} else if (type === "checkout.session.expired" || type === "checkout.session.async_payment_failed") {
  await ctx.db.update("payment", id, { status: "failed" });
  ctx.log(`stripe: payment ${id} not completed (${type})`);
}

const key = await ctx.secrets.get("STRIPE_SECRET_KEY");
if (!key) throw new Error("Payments aren't set up yet.");
const id = String(input["payment_id"] ?? "");
const pay = await ctx.db.get("payment", id);
if (!pay) throw new Error("That payment isn't yours or doesn't exist.");
if (String(pay["status"]) !== "pending") return { status: String(pay["status"]) };
const res = await ctx.http.fetch(`https://api.stripe.com/v1/checkout/sessions/${encodeURIComponent(String(pay["stripe_session_id"] ?? ""))}`, { headers: { authorization: `Bearer ${key}` } });
const s = res.ok ? res.json<{ status?: string; payment_status?: string; amount_total?: number | null }>() : null;
if (!s) return { status: "pending" };
const expected = Math.round(Number(pay["amount"] ?? 0) * 100);
const status = s.payment_status === "paid" && s.amount_total === expected ? "paid" : s.status === "expired" ? "failed" : "pending";
if (status === "pending") return { status };
await ctx.vars.set(`stripe-payment:${id}`, { status, at: new Date().toISOString() });
await ctx.db.update("payment", id, { check: "requested" });
return { status };

const key = `stripe-payment:${String(row["id"])}`;
const v = await ctx.vars.get(key);
const s = (v && typeof v === "object" ? v : {}) as Record<string, unknown>;
const patch: Record<string, unknown> = { check: "idle" };
if (s["status"] === "paid" || s["status"] === "failed") {
  patch["status"] = s["status"];
  if (s["status"] === "paid") patch["paid_at"] = String(s["at"] ?? ctx.now().toISOString());
}
await ctx.db.update("payment", String(row["id"]), patch);
await ctx.vars.set(key, null);
